      try {
        session = await getSession()
      } catch (err) {
        console.error(`Signed in, but couldn't reach DocuGate to confirm who you are: ${(err as Error).message}`)
        process.exitCode = 1
        return
      }
      if (session.user) {
        console.log(`@${session.user.githubLogin}`)
      } else {
        console.log('Not signed in. Run docugate login.')
      }
