      }
    } catch {
      // can't reach server; treat as not signed in
    }

    if (!signedIn) {
      let doLogin = yes
      if (!yes) {
        const answer = await io.ask('Sign in to DocuGate now? [Y/n]', 'y')
        doLogin = !/^n(o)?$/i.test(answer)
      }
      if (doLogin) {
        try {
          await loginFn(BASE_URL)
          signedIn = true
          io.print(`  Signed in to DocuGate.`)
        } catch (err) {
